create table if not exists distribution_platforms(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,active boolean not null default true,requires_isrc boolean not null default true,requires_upc boolean not null default false,status text not null default 'NOT_CONFIGURED',created_at timestamptz not null default now());
insert into distribution_platforms(code,name,requires_isrc,requires_upc) values ('SPOTIFY','Spotify',true,true),('APPLE_MUSIC','Apple Music',true,true),('YOUTUBE_MUSIC','YouTube Music',true,true),('DEEZER','Deezer',true,true),('AMAZON_MUSIC','Amazon Music',true,true),('TIKTOK','TikTok',true,false),('INSTAGRAM','Instagram',true,false),('FACEBOOK','Facebook',true,false),('YOUTUBE_SHORTS','YouTube / Shorts',true,false),('OTHER','Outras plataformas',true,false) on conflict(code) do nothing;
create table if not exists distribution_orders(id uuid primary key default gen_random_uuid(),release_id uuid not null references releases(id) on delete restrict,artist_id uuid not null references artists(id) on delete restrict,product_code text not null,amount numeric(18,2) not null,currency text not null default 'AOA',status text not null default 'READY',submitted_at timestamptz,completed_at timestamptz,error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_distribution_orders_artist on distribution_orders(artist_id,created_at desc);
create table if not exists distribution_deliveries(id uuid primary key default gen_random_uuid(),order_id uuid not null references distribution_orders(id) on delete cascade,platform_id uuid not null references distribution_platforms(id),status text not null default 'READY',external_release_id text,external_url text,error_code text,error_message text,submitted_at timestamptz,delivered_at timestamptz,published_at timestamptz,updated_at timestamptz not null default now(),unique(order_id,platform_id));
create table if not exists distribution_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references distribution_orders(id) on delete cascade,delivery_id uuid references distribution_deliveries(id) on delete set null,old_status text,new_status text not null,message text,actor_user_id uuid references users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists catalog_migrations(id uuid primary key default gen_random_uuid(),release_id uuid not null references releases(id) on delete restrict,artist_id uuid not null references artists(id) on delete restrict,previous_distributor text not null,old_isrc text,old_upc text,original_release_date date,platform_links jsonb not null default '{}'::jsonb,old_status text,migration_status text not null default 'DRAFT',preserve_identity boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
